/* Level overlay code; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"
#include "rnc/data_labels.h"
#include "rnc/math/asm_helpers.h"
#include "rnc/weapons/suck_aim.h"

/* Set an attached effect's alpha from distance and the supplied scale. */
/* Ported from rac1-decomp (src/overlays/l18/mobyutil_00267000.c: func_L18_00267000), where it is exact; names translated to the US level program. */

typedef struct {
    char  pad0[0x10];
    float position[4];
} Level18Moby;

typedef struct {
    char          pad0[0xA];
    unsigned char alpha;
} Level18Effect;

void set_moby_attached_effect_alpha_from_distance(Level18Moby *moby,
                                                  float        scale) __asm__("FUN_L18_00265ff8");

void set_moby_attached_effect_alpha_from_distance(Level18Moby *moby, float scale) {
    Level18Effect *effect;
    int            alpha;

    if (moby == 0) {
        return;
    }
    effect = suck_get_aim_height(moby);
    if (effect == 0) {
        return;
    }
    alpha =
        truncate_float_to_s32(fast_vec_dist(D_0013E533 + 0xE9D, moby->position) * 8.0f * scale) - 1;
    if (alpha >= 256) {
        alpha = 255;
    } else if (alpha < 0) {
        alpha = 0;
    }
    effect->alpha = alpha;
}
